WITH flattened AS (SELECT id, plan, effective_from, currency, EXPLODE_OUTER(discounts) AS tier_value FROM price_tiers) SELECT id, plan, tier_value, PERCENT_RANK() OVER (PARTITION BY plan ORDER BY tier_value DESC NULLS FIRST) AS tier_value_percent_rank, DENSE_RANK() OVER (ORDER BY tier_value DESC NULLS LAST) AS tier_value_dense_rank, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('week', effective_from), currency ORDER BY tier_value ASC) AS tier_value_dense_rank_2 FROM flattened WHERE MONTH(effective_from) IN (2, 10, 12)
